  const optionId = checkbox.id;
  const isChecked = checkbox.checked;

  // Store answer in state
  const formData = new FormData(document.getElementById('quizForm'));
  window.quizState = window.quizState || {};

  if (isChecked) {
    window.quizState[optionId] = true;
  } else {
    delete window.quizState[optionId];
  }
};

// Handle form submission
function handleSubmit(e) {
  e.preventDefault();

  const quiz = createQuiz();
  window.quizState = window.quizState || {};

  // Calculate score
  let correctCount = 0;
  let totalCorrectAnswers = 0;

  quiz.questions.forEach((question) => {
    const selectedAnswers = question.options
      .filter((option) => window.quizState[option.id])
      .map((option) => option.id);

    totalCorrectAnswers += question.correctAnswers.length;

    // Check if selected answers match correct answers exactly
    const isCorrect =
      selectedAnswers.length === question.correctAnswers.length &&
      selectedAnswers.every((answer) => question.correctAnswers.includes(answer));

    if (isCorrect) {
      correctCount++;
    }
  });

  // Display result
  const resultDiv = document.getElementById('resultMessage');
  const score = `${correctCount} / ${quiz.questions.length}`;
  const percentage = Math.round((correctCount / quiz.questions.length) * 100);

  let message = `You scored ${score} (${percentage}%)`;
  let resultClass = percentage >= 60 ? 'success' : 'info';

  if (percentage === 100) {
    message = `Perfect! You got all ${quiz.questions.length} questions correct!`;
  } else if (percentage >= 60) {
    message = `Great job! You scored ${score} (${percentage}%)`;
  }

  resultDiv.textContent = message;
  resultDiv.className = `result-message ${resultClass}`;
}

// Reset quiz
window.resetQuiz = function () {
  window.quizState = {};
  const resultDiv = document.getElementById('resultMessage');
  resultDiv.innerHTML = '';
  renderQuiz();
};

// Initialize quiz on page load
document.addEventListener('DOMContentLoaded', renderQuiz);
